import random
import string


class MemoryStore:
    def __init__(self):
        self._data = {}
        self._code_to_url = {}

    def save(self, short_code, url, ttl=None):
        self._data[short_code] = {'url': url, 'ttl': ttl, 'clicks': 0}
        self._code_to_url[short_code] = url

    def get(self, short_code):
        return self._data.get(short_code)

    def exists(self, short_code):
        return short_code in self._data

    def list_all(self):
        return list(self._data.keys())

    def increment_click(self, short_code):
        if short_code in self._data:
            self._data[short_code]['clicks'] += 1


def generate_short_code(length=6):
    alphabet = string.ascii_letters + string.digits
    return ''.join(random.choices(alphabet, k=length))

from storage import MemoryStore, generate_short_code


class URLShortener:
    def __init__(self, store=None):
        self.store = store if store is not None else MemoryStore()

    def shorten(self, url, custom_code=None):
        if custom_code:
            if self.store.exists(custom_code):
                raise ValueError('Code already in use')
            code = custom_code
        else:
            code = generate_short_code()
            while self.store.exists(code):
                code = generate_short_code()
        self.store.save(code, url)
        return code

    def resolve(self, short_code):
        record = self.store.get(short_code)
        if record is None:
            raise ValueError('Code not found')
        self.store.increment_click(short_code)
        return record['url']

    def stats(self, short_code):
        record = self.store.get(short_code)
        if record is None:
            raise ValueError('Code not found')
        return {
            'short_code': short_code,
            'url': record['url'],
            'clicks': record['clicks'],
            'ttl': record['ttl'],
        }

    def batch_shorten(self, urls):
        results = []
        for url in urls:
            code = self.shorten(url)
            results.append({'url': url, 'short_code': code})
        return results

