import re


def validate_url(url):
    if not url:
        raise ValueError('URL is required')
    if not url.startswith(('http://', 'https://')):
        raise ValueError('URL must start with http:// or https://')
    return url


def validate_custom_code(code):
    if not code:
        return True
    if len(code) < 3 or len(code) > 30:
        raise ValueError('Custom code must be 3-30 characters')
    if not re.match(r'^[A-Za-z0-9_-]+$', code):
        raise ValueError('Custom code can only contain letters, numbers, hyphens and underscores')
    return True

class Room:
    def __init__(self, room_id, name, capacity):
        self.room_id = room_id
        self.name = name
        self.capacity = capacity
        self.schedule = []

    def is_available(self, start, end):
        for block in self.schedule:
            # overlap check
            if start < block['end'] and end > block['start']:
                return False
        return True

    def book(self, meeting_id, start, end, organizer):
        if not self.is_available(start, end):
            raise ValueError('Room not available')
        self.schedule.append({'meeting_id': meeting_id, 'start': start, 'end': end, 'organizer': organizer})
        return True

    def cancel(self, meeting_id):
        self.schedule = [b for b in self.schedule if b['meeting_id'] != meeting_id]

    def meetings_at(self, day):
        return [b for b in self.schedule if block['start'].date() == day]

    def utilization(self):
        # TODO: implement utilization percentage for this room
        raise NotImplementedError('Calculate room utilization percentage')

