class Scheduler:
    def __init__(self, rooms=None):
        self.rooms = rooms if rooms is not None else []
        self._meeting_map = {}
        self._id_counter = 1

    def find_room(self, capacity, start, end):
        for room in self.rooms:
            if room.capacity >= capacity and room.is_available(start, end):
                return room
        return None

    def schedule_meeting(self, title, capacity, start, end, organizer):
        room = self.find_room(capacity, start, end)
        if room is None:
            raise ValueError('No room available')
        meeting_id = f'M{self._id_counter}'
        self._id_counter += 1
        room.book(meeting_id, start, end, organizer)
        self._meeting_map[meeting_id] = {
            'meeting_id': meeting_id,
            'title': title,
            'room': room.room_id,
            'start': start,
            'end': end,
            'organizer': organizer,
        }
        return meeting_id

    def cancel_meeting(self, meeting_id):
        info = self._meeting_map.pop(meeting_id, None)
        if info is None:
            raise ValueError('Meeting not found')
        room = next((r for r in self.rooms if r.room_id == info['room']), None)
        if room:
            room.cancel(meeting_id)

    def list_meetings(self, room_id=None):
        if room_id:
            return [m for m in self._meeting_map.values() if m['room'] == room_id]
        return list(self._meeting_map.values())

