def detect_conflicts(schedule_blocks):
    conflicts = []
    for i in range(len(schedule_blocks)):
        for j in range(i + 1, len(schedule_blocks)):
            a = schedule_blocks[i]
            b = schedule_blocks[j]
            if a['start'] < b['end'] and b['start'] < a['end']:
                conflicts.append((a['meeting_id'], b['meeting_id']))
    return conflicts


