def format_notification(meeting, minutes_before=15):
    delta = datetime.timedelta(minutes=minutes_before)
    remind_at = meeting['start'] - delta
    return {
        'recipient': meeting['organizer'],
        'message': f"Meeting '{meeting['title']}' starts at {meeting['start'].strftime('%H:%M')}",
        'remind_at': remind_at,
    }


